#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
# Copyright 2026 Firelock, LLC
"""Generate the Windows rehearsal from the actual public install proof.

The commands and assertions come from install-proof.yml. Only the trigger,
matrix and receipt steps differ. --check rejects stale generated workflows.
"""
from __future__ import annotations

import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
HEADER = '''# SPDX-License-Identifier: Apache-2.0
# Copyright 2026 Firelock, LLC
# Generated by scripts/generate-release-rehearsal.py. Do not edit by hand.
name: Rehearse Windows release proof
on:
  workflow_call:
    inputs:
      candidate_sha:
        required: true
        type: string
      source_path:
        required: false
        type: string
        default: '.'
      release_tag:
        required: false
        type: string
        default: v0.8.6
      proof_mode:
        required: true
        type: string
      local_artifact:
        required: false
        type: string
        default: ''
permissions:
  contents: read
  attestations: read
# The leg runs on a 16-core Depot Windows runner, the one rc-build.yml builds the
# Windows archive on, unless the KIN_RC_USE_GITHUB_RUNNERS outage switch selects
# windows-latest. Its name stays windows-latest either way, because release
# verification finds the leg by that job name. Git's long path support is on
# because the deepest tracked fixture passes Windows' 260-character limit
# under the Depot runner's longer work directory.
#
# The installer proofs change the user PATH, so they run only on a disposable
# account. Depot runs each job on a single-use VM that GitHub reports as
# self-hosted, so the job declares it with KIN_DISPOSABLE_RUNNER=depot, set
# only when the Depot runner is selected. The proofs admit a self-hosted runner
# only with that declaration, a depot- runner name and Depot's DEPOT_ORG_ID.
'''
SETUP = r'''      - name: Require the workflow context candidate before checkout
        shell: bash
        env:
          CANDIDATE: ${{ inputs.candidate_sha }}
          CONTEXT_SHA: ${{ github.sha }}
        run: |
          set -euo pipefail
          if [[ ! "$CONTEXT_SHA" =~ ^[0-9a-f]{40}$ || "$CANDIDATE" != "$CONTEXT_SHA" ]]; then
            echo "::error::Rehearsal candidate must equal the actual workflow context SHA"
            exit 1
          fi
      - name: Preserve canonical candidate source bytes
        shell: bash
        run: |
          git config --global core.autocrlf false
          git config --global core.longpaths true
      - name: Checkout the exact rehearsal source
        uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          ref: ${{ github.sha }}
          path: rehearsal-source
          fetch-depth: 1
          persist-credentials: false
      - name: Bind the rehearsal source and stable baseline
        shell: bash
        env:
          CANDIDATE: ${{ inputs.candidate_sha }}
          SOURCE_PATH: ${{ inputs.source_path }}
          BASELINE_TAG: ${{ inputs.release_tag }}
          PROOF_MODE: ${{ inputs.proof_mode }}
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          python "rehearsal-source/$SOURCE_PATH/scripts/release-rehearsal.py" bind \
            --source "rehearsal-source/$SOURCE_PATH" --candidate "$CANDIDATE" \
            --release-tag "$BASELINE_TAG" --mode "$PROOF_MODE"
      - name: Prove the Windows file mirror checksum boundary
        if: inputs.proof_mode == 'compatibility-baseline'
        shell: pwsh
        env:
          SOURCE_PATH: ${{ inputs.source_path }}
        run: |
          $ErrorActionPreference = "Stop"
          & "rehearsal-source/$env:SOURCE_PATH/scripts/test-windows-install-mirror.ps1" -InstallerPath "rehearsal-source/$env:SOURCE_PATH/scripts/install.ps1" -OutputRoot "$env:RUNNER_TEMP/rehearsal/mirror-boundary" -RetainBaselineArchive
      - name: Prepare verified legacy baseline and rehearse its setup
        if: inputs.proof_mode == 'compatibility-baseline'
        shell: bash
        env:
          SOURCE_PATH: ${{ inputs.source_path }}
        run: |
          set -euo pipefail
          python "rehearsal-source/$SOURCE_PATH/scripts/release-rehearsal-compat.py" \
            --baseline-archive "$RUNNER_TEMP/rehearsal/mirror-boundary/kin-windows-x86_64.zip" \
            --output "$RUNNER_TEMP/rehearsal/compatibility"
'''
PREPARE = r'''      - name: Prepare candidate Windows installer and exact metadata
        if: inputs.proof_mode == 'candidate-full'
        shell: bash
        env:
          CANDIDATE: ${{ inputs.candidate_sha }}
          SOURCE_PATH: ${{ inputs.source_path }}
        run: |
          set -euo pipefail
          python "rehearsal-source/$SOURCE_PATH/scripts/release-rehearsal.py" stage-candidate \
            --source "rehearsal-source/$SOURCE_PATH" --candidate "$CANDIDATE" \
            --directory "$RUNNER_TEMP/kin-pull-request-release"
'''
RECEIPT = r'''      - name: Record the real Windows rehearsal
        shell: bash
        env:
          CANDIDATE: ${{ inputs.candidate_sha }}
          SOURCE_PATH: ${{ inputs.source_path }}
          BASELINE_TAG: ${{ inputs.release_tag }}
          PROOF_MODE: ${{ inputs.proof_mode }}
        run: |
          set -euo pipefail
          python "rehearsal-source/$SOURCE_PATH/scripts/release-rehearsal.py" record \
            --source "rehearsal-source/$SOURCE_PATH" --candidate "$CANDIDATE" \
            --release-tag "$BASELINE_TAG" --mode "$PROOF_MODE" --leg windows \
            --output "$RUNNER_TEMP/rehearsal/windows.json"
      - name: Upload the Windows rehearsal receipt
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.0
        with:
          name: release-rehearsal-windows
          path: ${{ runner.temp }}/rehearsal/windows.json
          if-no-files-found: error
          retention-days: 30
      - name: Preserve baseline compatibility captures
        if: always() && inputs.proof_mode == 'compatibility-baseline'
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.0
        with:
          name: release-rehearsal-compatibility-captures
          path: |
            ${{ runner.temp }}/rehearsal/compatibility
            ${{ runner.temp }}/rehearsal/mirror-boundary
          if-no-files-found: warn
          retention-days: 30
'''


def render(source: str) -> str:
    body = source.split('\njobs:\n', 1)[1].split('\n  update-proof:', 1)[0]
    # Comments and old ticket references are not part of the proof contract.
    # Keep newly generated contributor-facing lines free of tracker identifiers.
    body = '\n'.join(line for line in body.splitlines()
                     if not line.lstrip().startswith(('#', '//')))
    body = re.sub(r'FIR-\d+', 'the health-join update', body)
    body, count = re.subn(r'^        include: .*$',
        '        include: [{"os":"windows-latest","runner":"depot-windows-2022-16","setup-shell":"powershell"}]',
        body, flags=re.M)
    body, runners = re.subn(r'^    runs-on: \$\{\{ matrix\.os \}\}$',
        "    runs-on: ${{ vars.KIN_RC_USE_GITHUB_RUNNERS == 'true' && matrix.os || matrix.runner }}\n"
        "    env:\n"
        "      KIN_DISPOSABLE_RUNNER: ${{ vars.KIN_RC_USE_GITHUB_RUNNERS != 'true' && 'depot' || '' }}",
        body, flags=re.M)
    if count != 1 or runners != 1 or body.count('    steps:\n') != 1:
        raise ValueError('install proof no longer has the reviewed single matrix job')
    blocks = re.split(r'(?m)(?=^      - name:)', body)
    for index in range(1, len(blocks)):
        block = blocks[index]
        if re.search(r'(?m)^        if:', block):
            block = re.sub(r'(?m)^        if: (.*)$',
                lambda m: "        if: inputs.proof_mode == 'candidate-full' && (" + m[1] + ")", block, count=1)
        else:
            first, rest = block.split('\n', 1)
            block = first + "\n        if: inputs.proof_mode == 'candidate-full'\n" + rest
        blocks[index] = block
    body = ''.join(blocks)
    body = body.replace('      - name: Pull request install (Windows)\n',
                        PREPARE + '      - name: Pull request install (Windows)\n', 1)
    body = body.replace('    steps:\n', '    steps:\n' + SETUP, 1)
    return HEADER + '\njobs:\n' + body.rstrip() + '\n\n' + RECEIPT


def generate(check: bool, private: Path | None = None) -> None:
    workflows = ROOT / '.github/workflows'
    outputs = {workflows / 'release-rehearsal-windows.yml':
               render((workflows / 'install-proof.yml').read_text())}
    if private:
        outputs[private / 'release-rehearsal-windows.yml'] = next(iter(outputs.values()))
        outputs[private / 'release-rehearsal.yml'] = (workflows / 'release-rehearsal.yml').read_text()
    for target, text in outputs.items():
        if check:
            if not target.is_file() or target.read_text() != text:
                raise ValueError(f'{target.name} is stale; regenerate the release rehearsal')
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--private-workflows', type=Path)
    args = parser.parse_args()
    generate(args.check, args.private_workflows)
